SELECT t.FILLING_ID, t.FILLING_LN_ID, t.FILL_ITEM, t.FILL_ITEM_CODE, nvl(t.FIELD1,0)FIELD1, nvl(t.FIELD2,0)FIELD2, nvl(t.FIELD3,0)FIELD3, nvl(t.FIELD4,0)FIELD4, nvl(t.FIELD5,0)FIELD5, nvl(t.FIELD6,0)FIELD6, nvl(t.FIELD7,0)FIELD7, nvl(t.FIELD8,0)FIELD8, nvl(t.FIELD9,0)FIELD9, nvl(t.FIELD10,0)FIELD10, nvl(t.FIELD11,0)FIELD11, nvl(t.FIELD12,0)FIELD12, nvl(t.FIELD13,0)FIELD13, nvl(t.FIELD14,0)FIELD14, nvl(t.FIELD15,0)FIELD15, nvl(t.FIELD16,0)FIELD16, (select f.fill_type from jc_fund_filling f where f.filling_id = t.filling_id)fill_type, (select f.fill_quarter from jc_fund_filling f where f.filling_id = t.filling_id)fill_quarter, (select f.fill_week from jc_fund_filling f where f.filling_id = t.filling_id)fill_week, (select f.fill_year from jc_fund_filling f where f.filling_id = t.filling_id)fill_year, ( nvl(t.FIELD1, 0) + nvl(t.FIELD2, 0) + nvl(t.FIELD3, 0) + nvl(t.FIELD4, 0) + nvl(t.FIELD5, 0) + nvl(t.FIELD6, 0) + nvl(t.FIELD7, 0) + nvl(t.FIELD8, 0) + nvl(t.FIELD9, 0) + nvl(t.FIELD10, 0) + nvl(t.FIELD11, 0) + nvl(t.FIELD12, 0) + nvl(t.FIELD13, 0) + nvl(t.FIELD14, 0) + nvl(t.FIELD15, 0) + nvl(t.FIELD16, 0) ) SUM_AMOUNT, t.CREATION_DATE FROM jc_fund_filling_ln t
