SELECT t.FILLING_ID, t.FILLING_LN_ID, t.FILL_ITEM, t.FILL_ITEM_CODE, t.FIELD1, t.FIELD2, t.FIELD3, t.FIELD4, t.FIELD5, t.FIELD6, t.FIELD7, t.FIELD8, t.FIELD9, t.FIELD10, t.FIELD11, t.FIELD12, t.FIELD13, t.FIELD14, t.FIELD15, t.FIELD16, (select f.fill_type from jc_fund_filling f where f.filling_id = t.filling_id)fill_type, (select f.unit_id from jc_fund_filling f where f.filling_id = t.filling_id)unit_id, (select f.fill_quarter from jc_fund_filling f where f.filling_id = t.filling_id)fill_quarter, (select f.fill_week from jc_fund_filling f where f.filling_id = t.filling_id)fill_week, (select f.fill_year from jc_fund_filling f where f.filling_id = t.filling_id)fill_year, (select f.fill_mon from jc_fund_filling f where f.filling_id = t.filling_id)fill_mon, ( nvl(t.FIELD1, 0) + nvl(t.FIELD2, 0) + nvl(t.FIELD3, 0) + nvl(t.FIELD4, 0) + nvl(t.FIELD5, 0) + nvl(t.FIELD6, 0) + nvl(t.FIELD7, 0) + nvl(t.FIELD8, 0) + nvl(t.FIELD9, 0) + nvl(t.FIELD10, 0) + nvl(t.FIELD11, 0) + nvl(t.FIELD12, 0) + nvl(t.FIELD13, 0) + nvl(t.FIELD14, 0) + nvl(t.FIELD15, 0) + nvl(t.FIELD16, 0) ) SUM_AMOUNT FROM jc_fund_filling_ln t
