SELECT CONCAT_ws( '~', t1.start_date, t1.end_date ) field1_prompt, t1.start_date as field1_start_date, t1.end_date as field1_end_date, ( SELECT CONCAT_ws( '~', t.start_date, t.end_date ) FROM jc_fund_plan_schedule t WHERE t.FILL_YEAR = t1.fill_year AND t.FILL_MON = t1.fill_mon AND t.FILL_WEEK = 2 ) field2_prompt, ( SELECT t.start_date FROM jc_fund_plan_schedule t WHERE t.FILL_YEAR = t1.fill_year AND t.FILL_MON = t1.fill_mon AND t.FILL_WEEK = 2 ) field2_start_date, ( SELECT t.end_date FROM jc_fund_plan_schedule t WHERE t.FILL_YEAR = t1.fill_year AND t.FILL_MON = t1.fill_mon AND t.FILL_WEEK = 2 ) field2_end_date, ( SELECT CONCAT_ws( '~', t.start_date, t.end_date ) FROM jc_fund_plan_schedule t WHERE t.FILL_YEAR = t1.fill_year AND t.FILL_MON = t1.fill_mon AND t.FILL_WEEK = 3 ) field3_prompt, ( SELECT t.start_date FROM jc_fund_plan_schedule t WHERE t.FILL_YEAR = t1.fill_year AND t.FILL_MON = t1.fill_mon AND t.FILL_WEEK = 3 ) field3_start_date, ( SELECT t.end_date FROM jc_fund_plan_schedule t WHERE t.FILL_YEAR = t1.fill_year AND t.FILL_MON = t1.fill_mon AND t.FILL_WEEK = 3 ) field3_end_date, ( SELECT CONCAT_ws( '~', t.start_date, t.end_date ) FROM jc_fund_plan_schedule t WHERE t.FILL_YEAR = t1.fill_year AND t.FILL_MON = t1.fill_mon AND t.FILL_WEEK = 4 ) field4_prompt, ( SELECT t.start_date FROM jc_fund_plan_schedule t WHERE t.FILL_YEAR = t1.fill_year AND t.FILL_MON = t1.fill_mon AND t.FILL_WEEK = 4 ) field4_start_date, ( SELECT t.end_date FROM jc_fund_plan_schedule t WHERE t.FILL_YEAR = t1.fill_year AND t.FILL_MON = t1.fill_mon AND t.FILL_WEEK = 4 ) field4_end_date FROM jc_fund_plan_schedule t1
1=1 and t1.fill_week = 1
and t1.fill_year = #{fillYear}
